def generate_carp_pattern(n: int) -> None:
    def generate_carpet(k: int) -> list:
        if k == 0:
            return [["#"]]

        prev_carpet = generate_carpet(k - 1)
        size = 3 ** (k - 1)
        new_carpet = [[""] * (3 * size) for _ in range(3 * size)]

        for i in range(3):
            for j in range(3):
                for x in range(size):
                    for y in range(size):
                        if i == 1 and j == 1:
                            new_carpet[i * size + x][j * size + y] = "."
                        else:
                            new_carpet[i * size + x][j * size + y] = prev_carpet[x][y]

        return new_carpet

    carpet = generate_carpet(n)
    for row in carpet:
        print("".join(row))

